Fn::Sub:
{
  "variables": [
    {
      "type": "property",
      "property": "EndpointName",
      "inputType": "select",
      "id": "endpointName",
      "label": "Endpoint",
      "visible": true,
      "search": "{AWS/SageMaker,EndpointName,VariantName} MetricName=\"Invocations\"",
      "populateFrom": "EndpointName",
      "defaultValue": "${EndpointName}"
    },
    {
      "type": "property",
      "property": "VariantName",
      "inputType": "select",
      "id": "variantName",
      "label": "Variant",
      "visible": true,
      "search": "{AWS/SageMaker,EndpointName,VariantName} MetricName=\"Invocations\" EndpointName=\"${EndpointName}\"",
      "populateFrom": "VariantName",
      "defaultValue": "${VariantName}"
    }
  ],
  "widgets": [
    {
      "type": "text",
      "x": 0,
      "y": 0,
      "width": 24,
      "height": 2,
      "properties": {
        "markdown": "# SageMaker Realtime Endpoint Dashboard\nEndpoint: `${EndpointName}` | Variant: `${VariantName}`\n\nLatency widgets convert SageMaker microsecond metrics to milliseconds using CloudWatch metric math."
      }
    },
    {
      "type": "metric",
      "x": 0,
      "y": 2,
      "width": 8,
      "height": 4,
      "properties": {
        "title": "Invocations",
        "region": "${AWS::Region}",
        "view": "singleValue",
        "metrics": [
          [
            "AWS/SageMaker",
            "Invocations",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "stat": "Sum",
              "label": "Invocations"
            }
          ]
        ],
        "period": 60,
        "setPeriodToTimeRange": true
      }
    },
    {
      "type": "metric",
      "x": 8,
      "y": 2,
      "width": 8,
      "height": 4,
      "properties": {
        "title": "Errors",
        "region": "${AWS::Region}",
        "view": "singleValue",
        "metrics": [
          [
            "AWS/SageMaker",
            "Invocation4XXErrors",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "stat": "Sum",
              "label": "4XX"
            }
          ],
          [
            ".",
            "Invocation5XXErrors",
            ".",
            ".",
            ".",
            ".",
            {
              "stat": "Sum",
              "label": "5XX"
            }
          ]
        ],
        "period": 60,
        "setPeriodToTimeRange": true
      }
    },
    {
      "type": "metric",
      "x": 16,
      "y": 2,
      "width": 8,
      "height": 4,
      "properties": {
        "title": "Model latency p95 (ms)",
        "region": "${AWS::Region}",
        "view": "singleValue",
        "metrics": [
          [
            "AWS/SageMaker",
            "ModelLatency",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "id": "m_model_p95",
              "stat": "p95",
              "visible": false
            }
          ],
          [
            {
              "expression": "m_model_p95/1000",
              "label": "Model p95 ms",
              "id": "e_model_p95"
            }
          ]
        ],
        "period": 60,
        "setPeriodToTimeRange": true
      }
    },
    {
      "type": "metric",
      "x": 0,
      "y": 6,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "Invocations and errors",
        "region": "${AWS::Region}",
        "view": "timeSeries",
        "stacked": false,
        "metrics": [
          [
            "AWS/SageMaker",
            "Invocations",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "stat": "Sum",
              "label": "Invocations"
            }
          ],
          [
            ".",
            "Invocation4XXErrors",
            ".",
            ".",
            ".",
            ".",
            {
              "stat": "Sum",
              "label": "4XX errors"
            }
          ],
          [
            ".",
            "Invocation5XXErrors",
            ".",
            ".",
            ".",
            ".",
            {
              "stat": "Sum",
              "label": "5XX errors"
            }
          ]
        ],
        "period": 60
      }
    },
    {
      "type": "metric",
      "x": 12,
      "y": 6,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "Error rate",
        "region": "${AWS::Region}",
        "view": "timeSeries",
        "metrics": [
          [
            "AWS/SageMaker",
            "Invocations",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "id": "m_inv",
              "stat": "Sum",
              "visible": false
            }
          ],
          [
            ".",
            "Invocation4XXErrors",
            ".",
            ".",
            ".",
            ".",
            {
              "id": "m_4xx",
              "stat": "Sum",
              "visible": false
            }
          ],
          [
            ".",
            "Invocation5XXErrors",
            ".",
            ".",
            ".",
            ".",
            {
              "id": "m_5xx",
              "stat": "Sum",
              "visible": false
            }
          ],
          [
            {
              "expression": "IF(m_inv>0,100*(m_4xx+m_5xx)/m_inv,0)",
              "label": "Error rate %",
              "id": "e_error_rate"
            }
          ]
        ],
        "yAxis": {
          "left": {
            "min": 0
          }
        },
        "period": 60
      }
    },
    {
      "type": "metric",
      "x": 0,
      "y": 12,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "Model latency percentiles (ms)",
        "region": "${AWS::Region}",
        "view": "timeSeries",
        "metrics": [
          [
            "AWS/SageMaker",
            "ModelLatency",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "id": "m_model_p50",
              "stat": "p50",
              "visible": false
            }
          ],
          [
            "...",
            {
              "id": "m_model_p75",
              "stat": "p75",
              "visible": false
            }
          ],
          [
            "...",
            {
              "id": "m_model_p90",
              "stat": "p90",
              "visible": false
            }
          ],
          [
            "...",
            {
              "id": "m_model_p95",
              "stat": "p95",
              "visible": false
            }
          ],
          [
            {
              "expression": "m_model_p50/1000",
              "label": "p50",
              "id": "e_model_p50"
            }
          ],
          [
            {
              "expression": "m_model_p75/1000",
              "label": "p75",
              "id": "e_model_p75"
            }
          ],
          [
            {
              "expression": "m_model_p90/1000",
              "label": "p90",
              "id": "e_model_p90"
            }
          ],
          [
            {
              "expression": "m_model_p95/1000",
              "label": "p95",
              "id": "e_model_p95"
            }
          ]
        ],
        "period": 60
      }
    },
    {
      "type": "metric",
      "x": 12,
      "y": 12,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "Overhead latency percentiles (ms)",
        "region": "${AWS::Region}",
        "view": "timeSeries",
        "metrics": [
          [
            "AWS/SageMaker",
            "OverheadLatency",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "id": "m_over_p50",
              "stat": "p50",
              "visible": false
            }
          ],
          [
            "...",
            {
              "id": "m_over_p75",
              "stat": "p75",
              "visible": false
            }
          ],
          [
            "...",
            {
              "id": "m_over_p90",
              "stat": "p90",
              "visible": false
            }
          ],
          [
            "...",
            {
              "id": "m_over_p95",
              "stat": "p95",
              "visible": false
            }
          ],
          [
            {
              "expression": "m_over_p50/1000",
              "label": "p50",
              "id": "e_over_p50"
            }
          ],
          [
            {
              "expression": "m_over_p75/1000",
              "label": "p75",
              "id": "e_over_p75"
            }
          ],
          [
            {
              "expression": "m_over_p90/1000",
              "label": "p90",
              "id": "e_over_p90"
            }
          ],
          [
            {
              "expression": "m_over_p95/1000",
              "label": "p95",
              "id": "e_over_p95"
            }
          ]
        ],
        "period": 60
      }
    },
    {
      "type": "metric",
      "x": 0,
      "y": 18,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "Host CPU / memory / disk utilization",
        "region": "${AWS::Region}",
        "view": "timeSeries",
        "metrics": [
          [
            "/aws/sagemaker/Endpoints",
            "CPUUtilization",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "stat": "Average",
              "label": "CPU avg"
            }
          ],
          [
            ".",
            "MemoryUtilization",
            ".",
            ".",
            ".",
            ".",
            {
              "stat": "Average",
              "label": "Memory avg"
            }
          ],
          [
            ".",
            "DiskUtilization",
            ".",
            ".",
            ".",
            ".",
            {
              "stat": "Average",
              "label": "Disk avg"
            }
          ]
        ],
        "yAxis": {
          "left": {
            "min": 0
          }
        },
        "period": 60
      }
    },
    {
      "type": "metric",
      "x": 12,
      "y": 18,
      "width": 12,
      "height": 6,
      "properties": {
        "title": "GPU utilization / memory",
        "region": "${AWS::Region}",
        "view": "timeSeries",
        "metrics": [
          [
            "/aws/sagemaker/Endpoints",
            "GPUUtilization",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "stat": "Average",
              "label": "GPU avg"
            }
          ],
          [
            "...",
            {
              "stat": "Maximum",
              "label": "GPU max"
            }
          ],
          [
            ".",
            "GPUMemoryUtilization",
            ".",
            ".",
            ".",
            ".",
            {
              "stat": "Average",
              "label": "GPU memory avg"
            }
          ],
          [
            "...",
            {
              "stat": "Maximum",
              "label": "GPU memory max"
            }
          ]
        ],
        "yAxis": {
          "left": {
            "min": 0
          }
        },
        "period": 60
      }
    },
    {
      "type": "metric",
      "x": 0,
      "y": 24,
      "width": 24,
      "height": 6,
      "properties": {
        "title": "Model and overhead latency p95 (ms)",
        "region": "${AWS::Region}",
        "view": "timeSeries",
        "metrics": [
          [
            "AWS/SageMaker",
            "ModelLatency",
            "EndpointName",
            "${EndpointName}",
            "VariantName",
            "${VariantName}",
            {
              "id": "m_model",
              "stat": "p95",
              "visible": false
            }
          ],
          [
            ".",
            "OverheadLatency",
            ".",
            ".",
            ".",
            ".",
            {
              "id": "m_over",
              "stat": "p95",
              "visible": false
            }
          ],
          [
            {
              "expression": "m_model/1000",
              "label": "Model p95 ms",
              "id": "e_model"
            }
          ],
          [
            {
              "expression": "m_over/1000",
              "label": "Overhead p95 ms",
              "id": "e_over"
            }
          ]
        ],
        "period": 60
      }
    },
    {
      "type": "log",
      "x": 0,
      "y": 30,
      "width": 24,
      "height": 6,
      "properties": {
        "title": "Endpoint errors",
        "region": "${AWS::Region}",
        "query": "SOURCE '/aws/sagemaker/Endpoints/${EndpointName}' | fields @timestamp, @message | filter @message like /ERROR|Error|Exception|Traceback|OOM|CUDA|timeout|Timed out/ | sort @timestamp desc | limit 100",
        "view": "table"
      }
    },
    {
      "type": "log",
      "x": 0,
      "y": 36,
      "width": 24,
      "height": 6,
      "properties": {
        "title": "Endpoint logs tail",
        "region": "${AWS::Region}",
        "query": "SOURCE '/aws/sagemaker/Endpoints/${EndpointName}' | fields @timestamp, @message | sort @timestamp desc | limit 100",
        "view": "table"
      }
    }
  ]
}
